begin;
create type public.record_status as enum ('draft','completed','locked','void');
create table public.records(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),laboratory_id uuid not null references public.laboratories(id),criterion_id uuid references public.criteria(id),record_code text not null,title text not null,status public.record_status not null default 'draft',occurred_at timestamptz not null default now(),retention_until date,created_by uuid not null references public.profiles(id),created_at timestamptz not null default now(),locked_at timestamptz,locked_by uuid references public.profiles(id),unique(laboratory_id,record_code));
create table public.record_files(id uuid primary key default gen_random_uuid(),record_id uuid not null references public.records(id) on delete restrict,storage_path text not null unique,file_name text not null,mime_type text not null,file_size bigint not null check(file_size>0 and file_size<=52428800),checksum_sha256 text not null check(checksum_sha256 ~ '^[a-f0-9]{64}$'),created_by uuid not null references public.profiles(id),created_at timestamptz not null default now());
create table public.record_signatures(id uuid primary key default gen_random_uuid(),record_id uuid not null references public.records(id) on delete restrict,record_snapshot_hash text not null check(record_snapshot_hash ~ '^[a-f0-9]{64}$'),signed_by uuid not null references public.profiles(id),signed_at timestamptz not null default now(),invalidated_at timestamptz,invalidated_reason text);
create type public.assessment_status as enum ('draft','in_review','approved','closed');
create table public.assessments(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),laboratory_id uuid not null references public.laboratories(id),title text not null,status public.assessment_status not null default 'draft',period_start date not null,period_end date not null,created_by uuid not null references public.profiles(id),created_at timestamptz not null default now(),approved_by uuid references public.profiles(id),approved_at timestamptz,check(period_end>=period_start));
create table public.assessment_items(id uuid primary key default gen_random_uuid(),assessment_id uuid not null references public.assessments(id) on delete cascade,criterion_id uuid not null references public.criteria(id),score numeric,comment text,status text not null default 'not_assessed' check(status in ('achieved','partial','not_achieved','not_assessed','not_applicable')),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(assessment_id,criterion_id));
create index records_scope_idx on public.records(organization_id,laboratory_id,criterion_id);
create index assessment_scope_idx on public.assessments(organization_id,laboratory_id,status);
create index assessment_items_assessment_idx on public.assessment_items(assessment_id);
alter table public.records enable row level security; alter table public.record_files enable row level security; alter table public.record_signatures enable row level security; alter table public.assessments enable row level security; alter table public.assessment_items enable row level security;
create policy records_read_scope on public.records for select to authenticated using(public.is_lab_admin() or exists(select 1 from public.profiles p where p.id=auth.uid() and p.status='approved' and p.laboratory_id=records.laboratory_id));
create policy assessments_read_scope on public.assessments for select to authenticated using(public.is_lab_admin() or exists(select 1 from public.profiles p where p.id=auth.uid() and p.status='approved' and p.laboratory_id=assessments.laboratory_id));
create policy assessment_items_verified_only on public.assessment_items for select to authenticated using(exists(select 1 from public.assessments a where a.id=assessment_items.assessment_id) and exists(select 1 from public.criteria c where c.id=assessment_items.criterion_id and c.verification_status='verified'));
commit;
